const STYLES=[['简洁写实','具体动作，克制表达'],['温柔治愈','细小善意，温暖细节'],['悬疑冷峻','线索铺陈，压迫节奏'],['诗意抒情','意象鲜明，留白充足'],['黑色幽默','荒诞反差，冷静叙述'],['史诗厚重','宏观冲突，群像命运'],['轻快日常','自然对话，生活趣味'],['童话寓言','清晰象征，想象世界'],['自定义','写下你的语言偏好']];
const TAGS=['成长','冒险','亲情','友情','爱情','悬疑','科幻','奇幻','治愈','生存','抉择','群像','反转','喜剧','社会','探索'];
